from collections import Counter

def count_sum_distribution():
    counts = Counter()
    for x in range(10):
        for y in range(10):
            for z in range(10):
                s = x + y + z
                counts[s] += 1
    return counts

counts = count_sum_distribution()
max_collision_rate = max(counts.values())
print(f"Maximum number of triplets for a single sum S: {max_collision_rate}")

